adcs_vec3_t r = {0,0,0};
double angle = 0.0, rate = 0.0, energy = 0.0;
unint32 prior_good = ag_state.good;
int invalid = 0;

/* 输出默认清零（不含 good，good 由各分支决定） */
ag_output.angle_rad = 0.0;
ag_output.rate_norm_rad_s = 0.0;
ag_output.rate_energy = 0.0;

/* 无效配置/输入检查 → latch FAULT，good 保持 prior count */
if ((ag_input.enable != 0) && (ag_input.enable != 1)) {
    invalid = 1;
} else if (!isfinite(ag_config.angle_limit_rad) ||
           !isfinite(ag_config.rate_limit_rad_s) ||
           (ag_config.angle_limit_rad < 0.0) ||
           (ag_config.rate_limit_rad_s < 0.0) ||
           (ag_config.angle_limit_rad > ADCS_PI) ||
           (ag_config.required < 1U) || (ag_config.required > 20U)) {
    invalid = 1;
} else if ((ag_input.current_q_bi == NULL) || (ag_input.target_q_bi == NULL) ||
           (ag_input.rate_rad_s == NULL)) {
    invalid = 1;
} else if (!isfinite(ag_input.current_q_bi->w) || !isfinite(ag_input.current_q_bi->x) ||
           !isfinite(ag_input.current_q_bi->y) || !isfinite(ag_input.current_q_bi->z) ||
           !isfinite(ag_input.target_q_bi->w) || !isfinite(ag_input.target_q_bi->x) ||
           !isfinite(ag_input.target_q_bi->y) || !isfinite(ag_input.target_q_bi->z) ||
           !adcs_is_finite_vec3(ag_input.rate_rad_s)) {
    invalid = 1;
} else if (adcs_quat_normalize(ag_input.current_q_bi, &q_cur) != ADCS_OK ||
           adcs_quat_normalize(ag_input.target_q_bi, &q_tgt) != ADCS_OK) {
    invalid = 1;
}

if (invalid) {
    ag_state.mode = AG_FAULT;
    ag_state.good = prior_good;            /* preserve prior count */
    ag_output.mode = AG_FAULT;
    ag_output.good = prior_good;
    return;
}

/* 禁用 → SLEW 且清零证据 */
if (ag_input.enable == 0) {
    ag_state.mode = AG_SLEW;
    ag_state.good = 0U;
    ag_output.mode = AG_SLEW;
    ag_output.good = 0U;
    return;
}

/* 正常计算：相对旋转、最短角、速率范数、能量 */
q_err = adcs_quat_multiply(&q_tgt, &adcs_quat_conjugate(&q_cur));
{
    double c = fabs(q_err.w);
    if (c > 1.0) c = 1.0;
    angle = 2.0 * acos(c);
}
r = *ag_input.rate_rad_s;
rate = adcs_vec3_norm(&r);
energy = adcs_vec3_dot(&r, &r);

ag_output.angle_rad = angle;
ag_output.rate_norm_rad_s = rate;
ag_output.rate_energy = energy;

/* 决策表 */
if ((angle <= ag_config.angle_limit_rad) && (rate <= ag_config.rate_limit_rad_s)) {
    if (ag_state.good < ag_config.required) {
        ag_state.good++;
    }
    if (ag_state.good >= ag_config.required) {
        ag_state.mode = AG_SETTLED;
        ag_state.good = ag_config.required;
    }
    /* else: preserve current mode */
    ag_output.mode = ag_state.mode;
    ag_output.good = ag_state.good;
} else {
    ag_state.mode = AG_SLEW;
    ag_state.good = 0U;
    ag_output.mode = AG_SLEW;
    ag_output.good = 0U;
}

